def source(ledger):
    return '''import hashlib,json,os,signal,stat,time,urllib.parse\nfrom pathlib import Path\np=Path("/tmp/qa-resume-20261008-child-ciivjupc");mp=p/"owner-manifest.json";m=json.loads(mp.read_bytes())\nexpected_manifest=%r;expected_proxy=%r;rogue=(44924,123661578,65534,"078fc5e8711442c8051d8c515a3f57bc1d22dcdb90e9b384af0c50916125b531")\ndef sha(x):return hashlib.sha256(Path(x).read_bytes()).hexdigest()\ndef start(pid):\n r=Path("/proc",str(pid),"stat").read_text();return int(r[r.rfind(")")+2:].split()[19])\ndef uid(pid):\n for x in Path("/proc",str(pid),"status").read_text().splitlines():\n  if x.startswith("Uid:"):return int(x.split()[1])\n raise RuntimeError("uid_missing")\ndef argv(pid):return [x.decode(errors="replace") for x in Path("/proc",str(pid),"cmdline").read_bytes().split(bytes([0])) if x]\ndef matches(row):\n pid=int(row["pid"]);return start(pid)==int(row["starttime"]) and uid(pid)==int(row["uid"])==65534 and sha("/proc/"+str(pid)+"/exe")==row["exe_sha256"] and any(a==str(p) or a.startswith(str(p)+os.sep) for a in argv(pid))\nds=p.lstat();raw=mp.read_bytes()\nif (ds.st_dev,ds.st_ino,ds.st_uid)!=(33,135,65534) or sha(mp)!=expected_manifest or m["node_id"]!="15961ef7-81b4-43f3-80c8-1b6977ca2aea" or m["agent_id"]!="agent-ab15a133-73cd-4025-8c97-f2ff37e000f5" or (p/"owner.marker").read_text()!=m["owner_marker"]:raise RuntimeError("owner_manifest_guard_failed")\nif sha(p/"ws_proxy.py")!=expected_proxy or not matches(m["child"]) or not matches(m["supervisor"]):raise RuntimeError("owned_process_or_proxy_guard_failed")\npid,start_expected,uid_expected,exe_expected=rogue\nactual_argv=argv(pid)\nexpected_argv=[m["supervisor"]["exe_path"],str(p/"supervisor.py"),str(p),m["proxy"]["bind_ip"],"192.168.100.209","18080",str(p/"controls.json"),str(p/"proxy-events.jsonl"),str(p/"supervisor.ready.json")]\ntry:valid=(start(pid)==start_expected and uid(pid)==uid_expected and sha("/proc/"+str(pid)+"/exe")==exe_expected and len(actual_argv)==len(expected_argv) and os.path.realpath(actual_argv[0])==os.path.realpath(expected_argv[0]) and actual_argv[1:]==expected_argv[1:] and any(x==str(p) or x.startswith(str(p)+os.sep) for x in actual_argv))\nexcept OSError:valid=False\nif not valid:raise RuntimeError("rogue_process_exact_identity_guard_failed_no_signal")\nos.kill(pid,signal.SIGTERM);end=time.monotonic()+6\nwhile time.monotonic()<end:\n try:\n  if start(pid)!=start_expected:break\n except OSError:break\n time.sleep(.1)\nelse:\n if start(pid)==start_expected and uid(pid)==uid_expected and sha("/proc/"+str(pid)+"/exe")==exe_expected and argv(pid)==actual_argv:os.kill(pid,signal.SIGKILL)\n end=time.monotonic()+3\n while time.monotonic()<end:\n  try:\n   if start(pid)!=start_expected:break\n  except OSError:break\n  time.sleep(.1)\n else:raise RuntimeError("rogue_process_stop_failed")\ncontrols=json.loads((p/"controls.json").read_text())\nif controls!={}:raise RuntimeError("unexpected_remote_fault_rule_active")\nconfig=Path(m["config"]["path"]);cs=config.lstat()\nif config.is_symlink() or stat.S_IMODE(cs.st_mode)!=0o600 or cs.st_uid!=65534:raise RuntimeError("private_child_config_guard_failed")\nvalues={}\nfor line in config.read_text().splitlines():\n k,sep,v=line.partition(":")\n if not sep:raise RuntimeError("child_config_shape_invalid")\n try:values[k.strip()]=json.loads(v.strip())\n except Exception:values[k.strip()]=v.strip()\nif values.get("agent_id")!=m["agent_id"] or hashlib.sha256(values.get("registration_token","").encode()).hexdigest()[:16]!=m["registration_token_fingerprint"]:raise RuntimeError("child_config_identity_or_fingerprint_failed")\nport=m["proxy"]["port"];values["hub_url"]="ws://"+m["proxy"]["bind_ip"]+":"+str(port)+"/"\nlines=[k+": "+(json.dumps(v,separators=(",",":")) if isinstance(v,str) else ("true" if v is True else "false" if v is False else json.dumps(v,separators=(",",":")))) for k,v in values.items()]\ntmp=config.with_suffix(".yaml.tmp");tmp.write_text("\\n".join(lines)+"\\n");os.chmod(tmp,0o600);os.chown(tmp,65534,65534);tmp.replace(config)\nready=p/"supervisor.ready.json"\nif ready.is_symlink() or not ready.is_file():raise RuntimeError("ready_file_private_identity_guard_failed")\nrst=ready.lstat()\nif rst.st_uid!=65534 or stat.S_IMODE(rst.st_mode)!=0o600:raise RuntimeError("ready_file_mode_owner_guard_failed")\nt=ready.with_suffix(".json.tmp");t.write_text(json.dumps({"port":port},separators=(",",":")));os.chmod(t,0o600);os.chown(t,65534,65534);t.replace(ready)\nif not matches(m["child"]) or not matches(m["supervisor"]):raise RuntimeError("manifest_process_changed_during_recovery")\nprint(json.dumps({"status":"PASS","rogue_pid":pid,"rogue_process_exact_argv_proven":True,"rogue_process_removed":True,"manifest_sha256":sha(mp),"manifest_port":port,"config_port":port,"ready_port":json.loads(ready.read_text())["port"],"config_mode":"0o600","config_uid":config.stat().st_uid,"proxy_sha256":sha(p/"ws_proxy.py"),"child":m["child"],"supervisor":m["supervisor"],"secret_values_emitted":False},separators=(",",":")))\n'''%(ledger['owner_manifest_sha256'],ledger['proxy_source_sha256'])


def main():
    ledger=json.loads((h.HERE/'owned-process-ledger.json').read_text())
    code=source(ledger);ast.parse(code)
    result=h.create_native4_command('BE-REMOTE-TTL-recover-failed-delay-harness',code,timeout=40)
    if result.get('status')!='SUCCESS' or not isinstance(result.get('output'),dict) or result['output'].get('status')!='PASS':raise RuntimeError('failed_delay_harness_recovery_failed')
    out=result['output'];h.atomic(h.HERE/'remote-delay-failed-harness-recovery.json',{'task_id':result['task_id'],'execution_id':result['execution_id'],'command_sha256':result['command_sha256'],'status':result['status'],'output':out})
    print(json.dumps(out,ensure_ascii=False))


if __name__=='__main__':main()
